                    <h2 id="public-POSTapi-v1-admin-products--id--upload-image">Admin Endpoint: Upload a specific Image extending the existing Product</h2>

<p>
</p>



<span id="example-requests-POSTapi-v1-admin-products--id--upload-image">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/admin/products/16/upload-image" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "is_thumbnail="\
    --form "image=@C:\Users\shiplu\AppData\Local\Temp\php7446.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/admin/products/16/upload-image"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('is_thumbnail', '');
body.append('image', document.querySelector('input[name="image"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

